window.SAOMD_STORIES[410401001]={"id":410401001,"branches":[],"frames":[{"id":1,"order":1,"actions":[{"uid":"410401001:1:1","speaker":"Asuna","text":"Hnngh...","pose":10020906,"background":"bg_04_inn_bed","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯……"},{"uid":"410401001:1:2","speaker":"Kirito","text":"","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401001:1:3","speaker":"Yui","text":"","pose":20090206,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":2,"order":2,"actions":[{"uid":"410401001:2:1","speaker":"Kirito","text":"Dammit, why isn't Asuna's debuff\ngoing away?!","pose":100115012,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"可恶，亚丝娜的debuff怎么还不消失？！"}]},{"id":3,"order":3,"actions":[{"uid":"410401001:3:1","speaker":"Yui","text":"Mommy, Daddy, I did a little\nresearch.","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"妈妈，爸爸，我做了一点研究。"}]},{"id":4,"order":4,"actions":[{"uid":"410401001:4:1","speaker":"Yui","text":"It seems \"Fatal Poison\" is a\nlimited-time ailment only\navailable for Halloween.","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"看来“致命毒药”是万圣节限定的期间限定疾病。"}]},{"id":5,"order":5,"actions":[{"uid":"410401001:5:1","speaker":"Kirito","text":"Fitting.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"合适。"}]},{"id":6,"order":6,"actions":[{"uid":"410401001:6:1","speaker":"Yui","text":"You can get one-use knives in the\ncastle that have it. It's also\none of the demons' special skills.","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"在拥有它的城堡中可以获得一次性刀具。这也是恶魔的特殊技能之一。"}]},{"id":7,"order":7,"actions":[{"uid":"410401001:7:1","speaker":"Yui","text":"Its effects are temporary, but it\nis impossible to use any existing\nitems to cure it.","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"其效果是暂时的，但无法使用现有的物品来治愈。"}]},{"id":8,"order":8,"actions":[{"uid":"410401001:8:1","speaker":"Asuna","text":"Well, I suppose that just means\nI'll have to wait it out...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯，我想这只是意味着我必须等待......"}]},{"id":9,"order":9,"actions":[{"uid":"410401001:9:1","speaker":"Yui","text":"Well, there's more... The biggest\nproblem with this poison...","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"嗯，还有……这个毒最大的问题……"}]},{"id":10,"order":10,"actions":[{"uid":"410401001:10:1","speaker":"Yui","text":"...is that it's highly infectious\nand will start spreading to other\nplayers and mobs.","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"……它的传染性很强，会开始传播给其他玩家和小怪。"}]},{"id":11,"order":11,"actions":[{"uid":"410401001:11:1","speaker":"Kirito","text":"What?!","pose":100115082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什么？！"}]},{"id":12,"order":12,"actions":[{"uid":"410401001:12:1","speaker":"Asuna","text":"Kirito, Yui, get away from me!\nHurry!","pose":100209082,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"桐人、结衣，离我远点！匆忙！"}]},{"id":13,"order":13,"actions":[{"uid":"410401001:13:1","speaker":"Kirito","text":"Fat chance! I'm not just gonna\nabandon you!","pose":100115012,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好机会！我不会就这样抛弃你！"}]},{"id":14,"order":14,"actions":[{"uid":"410401001:14:1","speaker":"Asuna","text":"I'll be fine if I just wait! We\nhave to do whatever it takes\nso we don't lose anyone else!","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我等一下就可以了！我们必须尽一切努力，以免失去任何人！"}]},{"id":15,"order":15,"actions":[{"uid":"410401001:15:1","speaker":"Kirito","text":"Alright... Come on, Yui.\nLet's go.","pose":100115022,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好吧……来吧，结衣。我们走吧。"}]},{"id":16,"order":16,"actions":[{"uid":"410401001:16:1","speaker":"Yui","text":"Okay, Daddy...","pose":200902062,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"好的，爸爸……"},{"uid":"410401001:16:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401001:16:3","speaker":"Kirito","text":"","pose":100115022,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":17,"order":17,"actions":[{"uid":"410401001:17:1","speaker":"Sinon","text":"Leafa's been poisoned?","pose":10040208,"background":"bg_event_devil_castle_01","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"莉法中毒了？"},{"uid":"410401001:17:2","speaker":"Silica","text":"","pose":10060406,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":""},{"uid":"410401001:17:3","speaker":"Yuuki","text":"","pose":10050102,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":18,"order":18,"actions":[{"uid":"410401001:18:1","speaker":"Silica","text":"Yes, the vampire got her with a\npoison breath attack...","pose":10060406,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"是的，吸血鬼用毒息攻击攻击了她……"}]},{"id":19,"order":19,"actions":[{"uid":"410401001:19:1","speaker":"Yuuki","text":"I looked up that ailment. Everyone\nis talking about it right now.","pose":10050102,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"我查了一下那个病。现在每个人都在谈论它。"}]},{"id":20,"order":20,"actions":[{"uid":"410401001:20:1","speaker":"Yuuki","text":"This \"Fatal Poison\" can't be cured\nby items and is crazy infectious.","pose":10050102,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"这种“致命毒”无法用物品治愈，并且具有疯狂的传染性。"}]},{"id":21,"order":21,"actions":[{"uid":"410401001:21:1","speaker":"Yuuki","text":"Players aren't the only ones who\ncan catch it, either. Enemy mobs\ncan too.","pose":10050102,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"玩家也不是唯一能抓住它的人。敌方小怪也可以。"}]},{"id":22,"order":22,"actions":[{"uid":"410401001:22:1","speaker":"Sinon","text":"Friend or foe, huh? I bet they\ncame up with this to shake up\nthe battle even more.","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"是友还是敌，嗯？我敢打赌他们想出这个来进一步改变这场战斗。"}]},{"id":23,"order":23,"actions":[{"uid":"410401001:23:1","speaker":"Silica","text":"Leafa's resting at a nearby inn\nright now, but we should all still\nbe really careful.","pose":10060407,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"莉法现在在附近的旅店休息，不过大家还是要小心一点。"}]},{"id":24,"order":24,"actions":[{"uid":"410401001:24:1","speaker":"Sinon","text":"Got it... Yuuki, go let the other\nplayers know.","pose":10040207,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"知道了...优纪，去让其他的玩家知道吧。"}]},{"id":25,"order":25,"actions":[{"uid":"410401001:25:1","speaker":"Yuuki","text":"Okay!","pose":10050107,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"好！"}]},{"id":26,"order":26,"actions":[{"uid":"410401001:26:1","speaker":"Eugeo","text":"Asuna is poisoned?","pose":10530203,"background":"bg_event_devil_castle_02","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"亚丝娜中毒了？"},{"uid":"410401001:26:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":27,"order":27,"actions":[{"uid":"410401001:27:1","speaker":"Kirito","text":"It's temporary, so she'll be back\non her feet in no time, but it is\nreally infectious.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"虽然是暂时的，很快就会恢复正常，但是真的很有感染力。"},{"uid":"410401001:27:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":28,"order":28,"actions":[{"uid":"410401001:28:1","speaker":"Kirito","text":"She's resting, but the two of you\nshould probably steer clear of\nher for the time being.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"她正在休息，不过你们两个还是暂时避开她吧。"},{"uid":"410401001:28:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":29,"order":29,"actions":[{"uid":"410401001:29:1","speaker":"Eugeo","text":"Alright.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"好的。"},{"uid":"410401001:29:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":30,"order":30,"actions":[{"uid":"410401001:30:1","speaker":"Kirito","text":"This poison doesn't just affect\nour enemies, but our allies too.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这种毒不仅影响我们的敌人，也影响我们的盟友。"},{"uid":"410401001:30:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":31,"order":31,"actions":[{"uid":"410401001:31:1","speaker":"Kirito","text":"If you see anyone trying to use\nit, you watch out.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"如果你看到有人试图使用它，你要小心了。"},{"uid":"410401001:31:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":32,"order":32,"actions":[{"uid":"410401001:32:1","speaker":"Alice","text":"Strange...","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"奇怪……"},{"uid":"410401001:32:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":33,"order":33,"actions":[{"uid":"410401001:33:1","speaker":"Kirito","text":"What is?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什么是？"},{"uid":"410401001:33:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":34,"order":34,"actions":[{"uid":"410401001:34:1","speaker":"Alice","text":"If this poison were artificial,\nI could understand that, but...","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"如果这个毒是人工的话我也能理解，但是……"},{"uid":"410401001:34:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":35,"order":35,"actions":[{"uid":"410401001:35:1","speaker":"Alice","text":"...it is something the creatures\nwho live here in the Dread Bastion\nare able to use.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"……这是居住在恐惧堡垒中的生物能够使用的东西。"}]},{"id":36,"order":36,"actions":[{"uid":"410401001:36:1","speaker":"Alice","text":"It makes no sense that there\nwould be no way to cure it.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"没有办法治愈，这没有道理。"}]},{"id":37,"order":37,"actions":[{"uid":"410401001:37:1","speaker":"Alice","text":"What would they do if they were\never infected by their own poison?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"如果他们被自己的毒感染了怎么办？"},{"uid":"410401001:37:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":38,"order":38,"actions":[{"uid":"410401001:38:1","speaker":"Kirito","text":"I'm not sure...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我不确定……"},{"uid":"410401001:38:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":39,"order":39,"actions":[{"uid":"410401001:39:1","speaker":"Eugeo","text":"True. In nature, poisonous\ncreatures always have some way\nof counteracting their toxins.","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"确实如此。在自然界中，有毒的生物总是有某种方式来抵消它们的毒素。"},{"uid":"410401001:39:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":40,"order":40,"actions":[{"uid":"410401001:40:1","speaker":"Yui","text":"Daddy, I don't know how we're\ngoing to explain this to them,\nbut...","pose":20090206,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"爸爸，我不知道该怎么跟他们解释，但是……"},{"uid":"410401001:40:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":41,"order":41,"actions":[{"uid":"410401001:41:1","speaker":"Yui","text":"...it's because that's how this\npoison was set up to function\nin the game...","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"……因为游戏里的毒药就是这样设定的……"}]},{"id":42,"order":42,"actions":[{"uid":"410401001:42:1","speaker":"Kirito","text":"Actually, Yui, I think they might\nbe onto something.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"其实结衣，我觉得他们可能是有什么想法。"}]},{"id":43,"order":43,"actions":[{"uid":"410401001:43:1","speaker":"Kirito","text":"The announcement only said no\nexisting item could cure it,\nnot that NOTHING could.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"公告只是说现有的物品无法治愈，并不是说NOTHING可以。"},{"uid":"410401001:43:2","speaker":"Yui","text":"","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":44,"order":44,"actions":[{"uid":"410401001:44:1","speaker":"Eugeo","text":"What are you and Yui discussing?","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你和结衣在讨论什么？"},{"uid":"410401001:44:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":45,"order":45,"actions":[{"uid":"410401001:45:1","speaker":"Kirito","text":"N-Nothing... Just agreeing that\nAlice is right. There must be\nsome way to counteract it.","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"没、没什么……只是同意爱丽丝是对的。必须有某种方法来抵消它。"},{"uid":"410401001:45:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":46,"order":46,"actions":[{"uid":"410401001:46:1","speaker":"Kirito","text":"Maybe it's still too early to know\nfor certain, but we should look\ninto it more.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"也许现在下结论还为时过早，但我们应该更深入地研究一下。"},{"uid":"410401001:46:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":47,"order":47,"actions":[{"uid":"410401001:47:1","speaker":"Leafa","text":"Maaaan, I'm soooo hungry...","pose":10030106,"background":"bg_04_inn_bed","item":"","illustration":"","speaker_zh":"莉法","text_zh":"妈啊，我好饿……"}]},{"id":48,"order":48,"actions":[{"uid":"410401001:48:1","speaker":"Leafa","text":"I shut myself up in this room so\nI wouldn't spread the poison\nto everyone, but...","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"我把自己关在这个房间里，这样就不会把毒传染给所有人，但是……"}]},{"id":49,"order":49,"actions":[{"uid":"410401001:49:1","speaker":"Leafa","text":"...I'm just dying for something\nto eat.","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"……我太想吃点东西了。"}]},{"id":50,"order":50,"actions":[{"uid":"410401001:50:1","speaker":"Silica","text":"Are you okay, Leafa?","pose":10060405,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"莉法，你还好吗？"},{"uid":"410401001:50:2","speaker":"Leafa","text":"","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":51,"order":51,"actions":[{"uid":"410401001:51:1","speaker":"Leafa","text":"D-Don't come in here, Silica!\nYou'll get poisoned!","pose":100301032,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"D、别进来，西莉卡！你会中毒的！"}]},{"id":52,"order":52,"actions":[{"uid":"410401001:52:1","speaker":"Silica","text":"I won't stay long... I just came\nsince I thought you must be\ngetting hungry.","pose":10060402,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"我不会久留的……我以为你一定饿了，所以才来的。"}]},{"id":53,"order":53,"actions":[{"uid":"410401001:53:1","speaker":"Silica","text":"So I brought you some food from\nthe inn.","pose":10060405,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"所以我给你带了一些客栈的食物。"}]},{"id":54,"order":54,"actions":[{"uid":"410401001:54:1","speaker":"Leafa","text":"Ooh, that smells amazing! Wait a\nsecond, is this pumpkin soup?!","pose":10030104,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"哦，闻起来太棒了！等一下，这是南瓜汤吗？！"}]},{"id":55,"order":55,"actions":[{"uid":"410401001:55:1","speaker":"Silica","text":"It is! They only serve it during\nthe Halloween season.","pose":10060405,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"是的！他们只在万圣节期间提供。"}]},{"id":56,"order":56,"actions":[{"uid":"410401001:56:1","speaker":"Silica","text":"I thought I'd get it for you since\nit's only around for a little\nwhile.","pose":10060404,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"我想我应该给你买一下，因为它才出现一段时间。"}]},{"id":57,"order":57,"actions":[{"uid":"410401001:57:1","speaker":"Leafa","text":"Thank you, Silica!","pose":10030104,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"谢谢西莉卡！"}]},{"id":58,"order":58,"actions":[{"uid":"410401001:58:1","speaker":"Silica","text":"I hope you like it!","pose":10060404,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"希望你喜欢！"}]},{"id":59,"order":59,"actions":[{"uid":"410401001:59:1","speaker":"Leafa","text":"*slurp* *slurp*... Aah, that's\nso good! It tastes like a warm\nhug... I feel so much better!","pose":100301041,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"*咕噜* *咕噜*...啊啊，太好了！尝起来就像一个温暖的拥抱……我感觉好多了！"}]},{"id":60,"order":60,"actions":[{"uid":"410401001:60:1","speaker":"Silica","text":"Hehe, I'm glad! Well, I should\nprobably get back to the battle\nnow...","pose":10060404,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"呵呵，很高兴！好吧，我现在应该回到战斗了……"}]},{"id":61,"order":61,"actions":[{"uid":"410401001:61:1","speaker":"Leafa","text":"Yeah... Huh? Wait, what?","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"是啊……啊？等等，什么？"}]},{"id":62,"order":62,"actions":[{"uid":"410401001:62:1","speaker":"Silica","text":"What's the matter, Leafa?","pose":10060408,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"怎么了，莉法？"}]},{"id":63,"order":63,"actions":[{"uid":"410401001:63:1","speaker":"Leafa","text":"I'm cured! I don't have Fatal\nPoison anymore!","pose":10030103,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"我痊愈了！我已经没有致命毒了！"}]},{"id":64,"order":64,"actions":[{"uid":"410401001:64:1","speaker":"Kirito","text":"You found a way to cure the\npoison?!","pose":10011508,"background":"bg_event_devil_castle_02","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你找到解毒的方法了？！"},{"uid":"410401001:64:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":65,"order":65,"actions":[{"uid":"410401001:65:1","speaker":"Yui","text":"Yes. It seems the pumpkins\nthat appear in this area can\ncounteract it.","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"是的。看来这个区域出现的南瓜可以抵消它。"}]},{"id":66,"order":66,"actions":[{"uid":"410401001:66:1","speaker":"Yui","text":"All the players are talking about\nit.","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"所有玩家都在谈论它。"}]},{"id":67,"order":67,"actions":[{"uid":"410401001:67:1","speaker":"Kirito","text":"That's definitely fitting for\nHalloween, but I don't think\nI've ever seen a pumpkin here...","pose":100115022,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"确实很适合万圣节，不过我好像没见过南瓜……"}]},{"id":68,"order":68,"actions":[{"uid":"410401001:68:1","speaker":"Yui","text":"Well, they are pretty rare items.","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"嗯，是相当稀有的物品。"},{"uid":"410401001:68:2","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":69,"order":69,"actions":[{"uid":"410401001:69:1","speaker":"Alice","text":"Pumpkins? Did I hear that\ncorrectly?","pose":10540103,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"南瓜？我没听错吗？"},{"uid":"410401001:69:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":70,"order":70,"actions":[{"uid":"410401001:70:1","speaker":"Kirito","text":"Alice, Eugeo, how did the battle\ngo at the front gates?","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"爱丽丝、尤吉欧，前门战况怎么样？"},{"uid":"410401001:70:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":71,"order":71,"actions":[{"uid":"410401001:71:1","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410401001:71:2","speaker":"Eugeo","text":"Well enough. We've pushed them\nback for the time being.","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"好吧。我们暂时将他们推迟了。"}]},{"id":72,"order":72,"actions":[{"uid":"410401001:72:1","speaker":"Eugeo","text":"But what was that about pumpkins?","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"但是南瓜是什么呢？"}]},{"id":73,"order":73,"actions":[{"uid":"410401001:73:1","speaker":"Alice","text":"If it is pumpkins you want, I have\nseen them growing in the castle's\ngarden.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"如果你想要的是南瓜，我在城堡的花园里见过它们。"},{"uid":"410401001:73:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":74,"order":74,"actions":[{"uid":"410401001:74:1","speaker":"Kirito","text":"What?!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什么？！"},{"uid":"410401001:74:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":75,"order":75,"actions":[{"uid":"410401001:75:1","speaker":"Alice","text":"I found them when I was\nfamiliarizing myself with the\ncastle before the siege.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"攻城前熟悉城堡时发现的。"},{"uid":"410401001:75:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":76,"order":76,"actions":[{"uid":"410401001:76:1","speaker":"Kirito","text":"Alice, you're amazing! Can you\nshow me where they are?","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"爱丽丝，你太棒了！你能告诉我他们在哪里吗？"},{"uid":"410401001:76:2","speaker":"Yui","text":"","pose":20090204,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":77,"order":77,"actions":[{"uid":"410401001:77:1","speaker":"Alice","text":"Of course.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"当然。"},{"uid":"410401001:77:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":78,"order":78,"actions":[{"uid":"410401001:78:1","speaker":"Asuna","text":"This stewed pumpkin is really\ngood...","pose":10020904,"background":"bg_04_inn_bed","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"这个炖南瓜真好吃……"},{"uid":"410401001:78:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":79,"order":79,"actions":[{"uid":"410401001:79:1","speaker":"Asuna","text":"It's so soft and sweet...\nThe perfect comfort food.","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"又软又甜……完美的安慰食物。"}]},{"id":80,"order":80,"actions":[{"uid":"410401001:80:1","speaker":"Kirito","text":"Did it work?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"有效果吗？"}]},{"id":81,"order":81,"actions":[{"uid":"410401001:81:1","speaker":"Asuna","text":"Yeah. The poison indicator is gone\nfrom my status screen. I'm all\nbetter.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯。中毒指示器从我的状态屏幕上消失了。我一切都好多了"},{"uid":"410401001:81:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":82,"order":82,"actions":[{"uid":"410401001:82:1","speaker":"Alice","text":"That is a relief. Now that we know\nhow to cure the poison, we have\nnothing to worry about.","pose":10540104,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"那就放心了。既然知道了解毒的方法，我们就没什么好担心的了。"},{"uid":"410401001:82:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":83,"order":83,"actions":[{"uid":"410401001:83:1","speaker":"Kirito","text":"Thank goodness!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"谢天谢地！"},{"uid":"410401001:83:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":84,"order":84,"actions":[{"uid":"410401001:84:1","speaker":"Asuna","text":"By the way, who made this?\nIt's the same as my recipe...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"请问这个是谁做的？和我的食谱一样..."},{"uid":"410401001:84:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":85,"order":85,"actions":[{"uid":"410401001:85:1","speaker":"Alice","text":"I did.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我做到了。"},{"uid":"410401001:85:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":86,"order":86,"actions":[{"uid":"410401001:86:1","speaker":"Alice","text":"I tried to replicate what you\ntaught me before, Asuna.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我试着复制你之前教我的东西，亚丝娜。"}]},{"id":87,"order":87,"actions":[{"uid":"410401001:87:1","speaker":"Alice","text":"Does it taste all right?","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"味道还好吗？"},{"uid":"410401001:87:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":88,"order":88,"actions":[{"uid":"410401001:88:1","speaker":"Asuna","text":"It's absolutely delicious!","pose":100209041,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"绝对好吃！"},{"uid":"410401001:88:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":89,"order":89,"actions":[{"uid":"410401001:89:1","speaker":"Alice","text":"O-Oh, good...","pose":105401061,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"哎哟，好啊……"},{"uid":"410401001:89:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":90,"order":90,"actions":[{"uid":"410401001:90:1","speaker":"Kirito","text":"Alright, now that Asuna's healed\nup, we can get back to the battle.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好了，既然亚丝娜已经痊愈了，我们就可以回去战斗了。"},{"uid":"410401001:90:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":91,"order":91,"actions":[{"uid":"410401001:91:1","speaker":"Eugeo","text":"We have the advantage with the\npumpkin field under our control.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我们有优势，南瓜田在我们的控制之下。"},{"uid":"410401001:91:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":92,"order":92,"actions":[{"uid":"410401001:92:1","speaker":"Kirito","text":"Right. We can use the poison\nwithout worrying about it\nbackfiring on us now.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"对啊。我们现在可以使用毒药而不用担心它会适得其反。"},{"uid":"410401001:92:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":93,"order":93,"actions":[{"uid":"410401001:93:1","speaker":"Player","text":"Attaaaaack!","pose":2,"background":"bg_event_devil_castle_02","item":"","illustration":"","speaker_zh":"玩家","text_zh":"攻击！"},{"uid":"410401001:93:2","speaker":"Eugeo","text":"","pose":10530203,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401001:93:3","speaker":"Alice","text":"","pose":10540103,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":94,"order":94,"actions":[{"uid":"410401001:94:1","speaker":"Player","text":"We have to do whatever it takes\nto make it to the garden and\nget those pumpkins!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家","text_zh":"我们必须不惜一切代价到达花园并获得那些南瓜！"}]},{"id":95,"order":95,"actions":[{"uid":"410401001:95:1","speaker":"Player","text":"Yeaaaaaah!","pose":3,"background":"","item":"","illustration":"","speaker_zh":"玩家","text_zh":"耶啊啊啊！"}]},{"id":96,"order":96,"actions":[{"uid":"410401001:96:1","speaker":"Eugeo","text":"What's got them so worked up?","pose":105302032,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"什么事让他们如此激动？"}]},{"id":97,"order":97,"actions":[{"uid":"410401001:97:1","speaker":"Alice","text":"They are acting more aggressive\nthan before... Why?","pose":105401032,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"他们表现得比以前更凶了……为什么？"},{"uid":"410401001:97:2","speaker":"Eugeo","text":"","pose":105302032,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":98,"order":98,"actions":[{"uid":"410401001:98:1","speaker":"Kirito","text":"I bet I can guess!","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我敢说我能猜到！"},{"uid":"410401001:98:2","speaker":"Asuna","text":"","pose":10020903,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":99,"order":99,"actions":[{"uid":"410401001:99:1","speaker":"Sinon","text":"I bet you can!","pose":10040204,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"我打赌你可以！"},{"uid":"410401001:99:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":100,"order":100,"actions":[{"uid":"410401001:100:1","speaker":"Asuna","text":"Sinonon!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"诗诺！"},{"uid":"410401001:100:2","speaker":"Kirito","text":"","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":101,"order":101,"actions":[{"uid":"410401001:101:1","speaker":"Sinon","text":"I heard that there were pumpkins\ngrowing inside the castle.","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"听说城堡里长着南瓜。"},{"uid":"410401001:101:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":102,"order":102,"actions":[{"uid":"410401001:102:1","speaker":"Sinon","text":"So all we have to do is take\ncontrol of those gardens, and\nvictory is all but assured.","pose":10040204,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"所以我们只要控制住那些花园，胜利就在握了。"},{"uid":"410401001:102:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":103,"order":103,"actions":[{"uid":"410401001:103:1","speaker":"Silica","text":"Which is why we decided to go\nfor a full-frontal assault!","pose":10060407,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"所以我们决定正面进攻！"},{"uid":"410401001:103:2","speaker":"Yuuki","text":"","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":104,"order":104,"actions":[{"uid":"410401001:104:1","speaker":"Kirito","text":"You knew about the gardens too...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你也知道花园……"},{"uid":"410401001:104:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":105,"order":105,"actions":[{"uid":"410401001:105:1","speaker":"Leafa","text":"Well, this battle was always going\nto be won by whoever controlled\nthe cure for that poison.","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"嗯，这场战斗总是由谁掌握了解毒药而获胜。"},{"uid":"410401001:105:2","speaker":"Sinon","text":"","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":106,"order":106,"actions":[{"uid":"410401001:106:1","speaker":"Yuuki","text":"So we came to take it!","pose":10050107,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"所以我们就来拿了！"},{"uid":"410401001:106:2","speaker":"Silica","text":"","pose":10060405,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":""}]},{"id":107,"order":107,"actions":[{"uid":"410401001:107:1","speaker":"Sinon","text":"Come on, everybody!","pose":10040201,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"大家加油！"},{"uid":"410401001:107:2","speaker":"Leafa","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":108,"order":108,"actions":[{"uid":"410401001:108:1","speaker":"Attackers","text":"HYAAAH!","pose":3,"background":"","item":"","illustration":"","speaker_zh":"攻击者","text_zh":"哈啊！"},{"uid":"410401001:108:2","speaker":"Sinon","text":"","pose":10040207,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410401001:108:3","speaker":"Leafa","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":109,"order":109,"actions":[{"uid":"410401001:109:1","speaker":"Kirito","text":"Hehe... Hahahaha!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"呵呵……哈哈哈哈！"},{"uid":"410401001:109:2","speaker":"Asuna","text":"","pose":10020903,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":110,"order":110,"actions":[{"uid":"410401001:110:1","speaker":"Asuna","text":"Why are you laughing?","pose":10020903,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你笑什么？"},{"uid":"410401001:110:2","speaker":"Kirito","text":"","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":111,"order":111,"actions":[{"uid":"410401001:111:1","speaker":"Alice","text":"Kirito?","pose":10540103,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"桐人？"},{"uid":"410401001:111:2","speaker":"Eugeo","text":"","pose":10530203,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":112,"order":112,"actions":[{"uid":"410401001:112:1","speaker":"Kirito","text":"Normally I'd have no issue sharing\nthe pumpkins with everyone—but\nnot this time.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"通常我会毫无问题地与大家分享南瓜——但这次不行。"},{"uid":"410401001:112:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":113,"order":113,"actions":[{"uid":"410401001:113:1","speaker":"Kirito","text":"We four are the lords of\nthe Dread Bastion!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我们四人是恐惧堡垒的领主！"},{"uid":"410401001:113:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":114,"order":114,"actions":[{"uid":"410401001:114:1","speaker":"Eugeo","text":"What is it, Kirito?","pose":105302032,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"桐人，什么事？"},{"uid":"410401001:114:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":115,"order":115,"actions":[{"uid":"410401001:115:1","speaker":"Asuna","text":"Um, you're really getting into\nthis whole \"dread lord\" role,\naren't you?","pose":100209042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯，你真的很喜欢这个“恐惧领主”的角色，不是吗？"},{"uid":"410401001:115:2","speaker":"Kirito","text":"","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":116,"order":116,"actions":[{"uid":"410401001:116:1","speaker":"Asuna","text":"Who knew you had such a flare\nfor the dramatic...","pose":100209022,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"谁知道你有这么大的戏剧天赋……"}]},{"id":117,"order":117,"actions":[{"uid":"410401001:117:1","speaker":"Kirito","text":"Let none so much as glance at a\npumpkin! Our enemies shall die\nin agony! Mwahahaha!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"南瓜谁都别看！我们的敌人将在痛苦中死去！哇哈哈！"},{"uid":"410401001:117:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":118,"order":118,"actions":[{"uid":"410401001:118:1","speaker":"Sinon","text":"You fiend!","pose":10040201,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"你这个恶魔！"},{"uid":"410401001:118:2","speaker":"Leafa","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":119,"order":119,"actions":[{"uid":"410401001:119:1","speaker":"Sinon","text":"Did you hear that, everyone? We\ncan't let him get away with this!\nWe have to destroy him!","pose":10040201,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"大家听到了吗？我们不能让他得逞！我们必须消灭他！"}]},{"id":120,"order":120,"actions":[{"uid":"410401001:120:1","speaker":"Leafa","text":"You got it!","pose":10030101,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"你懂了！"},{"uid":"410401001:120:2","speaker":"Sinon","text":"","pose":10040207,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":121,"order":121,"actions":[{"uid":"410401001:121:1","speaker":"Yuuki","text":"Down with the Dread Lord Kirito!","pose":10050104,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"打倒恐惧魔王桐人！"},{"uid":"410401001:121:2","speaker":"Silica","text":"","pose":10060407,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":""}]},{"id":122,"order":122,"actions":[{"uid":"410401001:122:1","speaker":"Silica","text":"Kirito, I'm sorry, but we're\ntaking you out!","pose":10060407,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"桐人，对不起，我们要带你出去了！"}]},{"id":123,"order":123,"actions":[{"uid":"410401001:123:1","speaker":"Kirito","text":"Gaaah...","pose":10011509,"background":"bg_event_devil_castle_02","item":"","illustration":"","speaker_zh":"桐人","text_zh":"啊啊啊……"},{"uid":"410401001:123:2","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410401001:123:3","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":124,"order":124,"actions":[{"uid":"410401001:124:1","speaker":"Yui","text":"Daddy! Are you okay?!","pose":20090206,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"爸爸！你还好吗？！"}]},{"id":125,"order":125,"actions":[{"uid":"410401001:125:1","speaker":"Kirito","text":"Th-They got me... I don't think\nI'll be getting back to the battle\nany time soon...","pose":100115022,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"他们、他们抓住了我……我想我不会很快回到战斗中……"},{"uid":"410401001:125:2","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401001:125:3","speaker":"Yui","text":"","pose":20090206,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":126,"order":126,"actions":[{"uid":"410401001:126:1","speaker":"Eugeo","text":"Understandable, considering all\nthe enemies you just had to\ndeal with.","pose":105302042,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"可以理解，考虑到你刚刚要对付的所有敌人。"},{"uid":"410401001:126:2","speaker":"Alice","text":"","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":127,"order":127,"actions":[{"uid":"410401001:127:1","speaker":"Alice","text":"You reap what you sow. Of course\nyour enemies will fight back after\nsuch foolish taunting.","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"一分耕耘，一分收获。当然，你的敌人会在这种愚蠢的嘲讽之后反击。"},{"uid":"410401001:127:2","speaker":"Eugeo","text":"","pose":105302042,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":128,"order":128,"actions":[{"uid":"410401001:128:1","speaker":"Kirito","text":"Ha ha... I was just trying to play\nthe best villain I could.","pose":100115042,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈……我只是想尽力扮演最好的反派而已。"},{"uid":"410401001:128:2","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401001:128:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":129,"order":129,"actions":[{"uid":"410401001:129:1","speaker":"Asuna","text":"Honestly, Kirito...","pose":10020910,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"老实说，桐人..."},{"uid":"410401001:129:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410401001:129:3","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":130,"order":130,"actions":[{"uid":"410401001:130:1","speaker":"Sinon","text":"This is it!","pose":10040204,"background":"bg_event_devil_castle_01","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"就是这个了！"},{"uid":"410401001:130:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":131,"order":131,"actions":[{"uid":"410401001:131:1","speaker":"Leafa","text":"We'll be able to cure all our\npoisoned allies with this many\npumpkins!","pose":10030104,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"用这么多南瓜我们就能治愈所有中毒的盟友！"}]},{"id":132,"order":132,"actions":[{"uid":"410401001:132:1","speaker":"Sinon","text":"Let's get to work fortifying this\nposition as our base! Bring\nthe others!","pose":10040201,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"让我们开始努力巩固这个基地地位吧！把其他人都带来！"},{"uid":"410401001:132:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":133,"order":133,"actions":[{"uid":"410401001:133:1","speaker":"Silica","text":"I can't imagine the demons are\ngoing to let us keep this field\nwithout a fight.","pose":10060407,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"我无法想象恶魔会让我们不战而屈人之兵。"},{"uid":"410401001:133:2","speaker":"Yuuki","text":"","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":134,"order":134,"actions":[{"uid":"410401001:134:1","speaker":"Yuuki","text":"Definitely not. But I won't let\nanyone get past me!","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"绝对不是。但我不会让任何人超越我！"},{"uid":"410401001:134:2","speaker":"Silica","text":"","pose":10060405,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":""}]},{"id":135,"order":135,"actions":[{"uid":"410401001:135:1","speaker":"Sinon","text":"This is a major bridgehead... Now\nthat we have it, this battle is all\nbut won!","pose":10040207,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"这是一座重要的桥头堡……有了它，这场战斗就已经胜利了！"},{"uid":"410401001:135:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":136,"order":136,"actions":[{"uid":"410401001:136:1","speaker":"Sinon","text":"Let's keep fighting until this\nDread Bastion falls!","pose":10040201,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"让我们继续战斗，直到这座恐惧堡垒陷落！"}]},{"id":137,"order":137,"actions":[{"uid":"410401001:137:1","speaker":"Leafa","text":"Yeah!","pose":10030104,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"嗯！"}]},{"id":138,"order":138,"actions":[{"uid":"410401001:138:1","speaker":"Kirito","text":"This message...","pose":10011508,"background":"bg_event_devil_castle_02","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这条消息……"},{"uid":"410401001:138:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410401001:138:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":139,"order":139,"actions":[{"uid":"410401001:139:1","speaker":"Yui","text":"It says the PvP battles are over.\nMeaning the battle for the Dread\nBastion is finished.","pose":20090206,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"PvP的战斗结束了。这意味着恐惧堡垒的战斗已经结束。"}]},{"id":140,"order":140,"actions":[{"uid":"410401001:140:1","speaker":"Yui","text":"It appears rewards have been sent,\nbased on each player's final\nresults.","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"根据每个玩家的最终成绩，奖励已经发送。"}]},{"id":141,"order":141,"actions":[{"uid":"410401001:141:1","speaker":"Asuna","text":"Unfortunately the attackers beat\nus back at the end...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"可惜最后被攻击者打败了……"}]},{"id":142,"order":142,"actions":[{"uid":"410401001:142:1","speaker":"Kirito","text":"Yeah...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是啊……"},{"uid":"410401001:142:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410401001:142:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":143,"order":143,"actions":[{"uid":"410401001:143:1","speaker":"Eugeo","text":"Um, so...","pose":10530203,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"嗯，所以……"},{"uid":"410401001:143:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":144,"order":144,"actions":[{"uid":"410401001:144:1","speaker":"Kirito","text":"That means we lost.","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那就意味着我们输了。"},{"uid":"410401001:144:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410401001:144:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":145,"order":145,"actions":[{"uid":"410401001:145:1","speaker":"Alice","text":"We were defeated... Kirito should\nnot have so readily taken up the\nmantle of villainy.","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我们被打败了……桐人不应该这么轻易地承担起邪恶的责任。"},{"uid":"410401001:145:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":146,"order":146,"actions":[{"uid":"410401001:146:1","speaker":"Alice","text":"All it did was pour oil on the\nfire.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这只不过是火上浇油而已。"},{"uid":"410401001:146:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":147,"order":147,"actions":[{"uid":"410401001:147:1","speaker":"Kirito","text":"Hahaha, I'm sorry...","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈哈，对不起……"},{"uid":"410401001:147:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410401001:147:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":148,"order":148,"actions":[{"uid":"410401001:148:1","speaker":"Sinon","text":"There you are.","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"给你了。"},{"uid":"410401001:148:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":149,"order":149,"actions":[{"uid":"410401001:149:1","speaker":"Asuna","text":"Sinonon and the others are here!","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"诗诺他们来了！"},{"uid":"410401001:149:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401001:149:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":150,"order":150,"actions":[{"uid":"410401001:150:1","speaker":"Leafa","text":"Hehe, looks like we won!","pose":10030104,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"呵呵，看来我们赢了！"},{"uid":"410401001:150:2","speaker":"Sinon","text":"","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":151,"order":151,"actions":[{"uid":"410401001:151:1","speaker":"Yuuki","text":"Taking the garden was what really\nclinched it for us!","pose":10050104,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"拿下花园才是我们真正的胜利！"},{"uid":"410401001:151:2","speaker":"Silica","text":"","pose":10060405,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":""}]},{"id":152,"order":152,"actions":[{"uid":"410401001:152:1","speaker":"Alice","text":"Grrr... The gall of you!","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"呜呜……你好胆啊！"},{"uid":"410401001:152:2","speaker":"Eugeo","text":"","pose":10530203,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":153,"order":153,"actions":[{"uid":"410401001:153:1","speaker":"Silica","text":"A-Alice, please put your sword\naway! We aren't at war anymore!","pose":100604082,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"A-爱丽丝，请收起你的剑！我们不再处于战争状态了！"},{"uid":"410401001:153:2","speaker":"Yuuki","text":"","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":154,"order":154,"actions":[{"uid":"410401001:154:1","speaker":"Alice","text":"Y-Yes, quite right...","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"对、对对对……"},{"uid":"410401001:154:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":155,"order":155,"actions":[{"uid":"410401001:155:1","speaker":"Eugeo","text":"Ha ha, we were just talking about\nhow it's all Kirito's fault that\nwe were defeated.","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"哈哈，我们刚才在说我们输了都是桐人的错。"},{"uid":"410401001:155:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":156,"order":156,"actions":[{"uid":"410401001:156:1","speaker":"Sinon","text":"Hehe, of course it is. We had the\nexact same conversation.","pose":10040204,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"呵呵，当然是啦。我们进行了完全相同的对话。"},{"uid":"410401001:156:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":157,"order":157,"actions":[{"uid":"410401001:157:1","speaker":"Leafa","text":"Totally!","pose":10030104,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"完全可以！"},{"uid":"410401001:157:2","speaker":"Sinon","text":"","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":158,"order":158,"actions":[{"uid":"410401001:158:1","speaker":"Kirito","text":"Not cool, guys!","pose":100115082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"不酷，伙计们！"},{"uid":"410401001:158:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410401001:158:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":159,"order":159,"actions":[{"uid":"410401001:159:1","speaker":"Yuuki","text":"The players really wanted justice\nserved after hearing Kirito say\nthose evil things.","pose":10050104,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"玩家听到桐人说出那些恶毒的话后，真的很想得到正义。"},{"uid":"410401001:159:2","speaker":"Silica","text":"","pose":10060405,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":""}]},{"id":160,"order":160,"actions":[{"uid":"410401001:160:1","speaker":"Silica","text":"Hehe, I could tell you were having\na lot of fun playing the bad guy,\nbut that was a big mistake.","pose":10060404,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"呵呵，我看得出你扮演坏人很开心，但那是一个很大的错误。"},{"uid":"410401001:160:2","speaker":"Yuuki","text":"","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":161,"order":161,"actions":[{"uid":"410401001:161:1","speaker":"Kirito","text":"*sigh* Yeah, I guess it was...","pose":100115022,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"*叹气* 是啊，我猜是……"},{"uid":"410401001:161:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410401001:161:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":162,"order":162,"actions":[{"uid":"410401001:162:1","speaker":"Eugeo","text":"We weren't fighting for the Divine\nObjects this time, so it's okay,\nbut please don't do that again.","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"这次我们不是为了神物而战，所以没关系，但请不要再这样了。"},{"uid":"410401001:162:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":163,"order":163,"actions":[{"uid":"410401001:163:1","speaker":"Kirito","text":"Sorry... the ability to\nroleplay like that is one of the\nbest things about VRMMOS...","pose":100115062,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"抱歉……这样的角色扮演能力是VRMMOS最好的事情之一……"},{"uid":"410401001:163:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410401001:163:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":164,"order":164,"actions":[{"uid":"410401001:164:1","speaker":"Kirito","text":"But If it's gonna get me ganged up\non like this, I never wanna be\na dread lord again...","pose":100115062,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但是如果这会让我像这样联合起来的话，我就再也不想当恐惧领主了……"}]},{"id":165,"order":165,"actions":[{"uid":"410401001:165:1","speaker":"Asuna","text":"Hehe, looks like you've learned\nyour lesson.","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呵呵，看来你吸取教训了。"}]}]};
